def find_largest_rect(arr, bg):
    h, w = arr.shape
    max_area = 0
    best_rect = None

    for r1 in range(h):
        for r2 in range(r1, h):
            for c1 in range(w):
                for c2 in range(c1, w):
                    # Extract subgrid
                    sub = arr[r1:r2+1, c1:c2+1]
                    # Check if all non-bg values are the same
