def find_hollow_rectangles(arr, h, w, val):
    """Find hollow rectangular frames of value 'val'"""
    rectangles = []

    for r in range(h):
        for c in range(w):
            for height in range(1, h - r + 1):
                for width in range(1, w - c + 1):
                    # Check if this forms a hollow rectangle boundary
                    is_boundary = True
                    for dr in range(height):
                        for dc in range(width):
                            rr, cc = r + dr, c + dc
                            # Only boundary cells should match val
                            on_boundary = dr == 0 or dr == height - 1 or dc == 0 or dc == width - 1
                            if on_boundary and arr[rr, cc] != val:
                                is_boundary = False
                                break
                        if not is_boundary:
                            break
                    if is_boundary or (height <= 1 and width <= 1):  # solid is also boundary
                        rectangles.append((r, c, height, width))

    return rectangles

